"""Create a portable, local review gallery without network dependencies."""
import html
import json
import pathlib

ROOT = pathlib.Path(__file__).resolve().parent
posts = json.loads((ROOT/'campaign.json').read_text())
receipt_path = ROOT/'release-verification.json'
receipt = json.loads(receipt_path.read_text()) if receipt_path.exists() else {}
live = receipt.get('status') == 'verified'
released_ids = {p['id'] for p in receipt.get('posts', [])} if live else set()
status_text = f'{receipt["updated_posts"]} posting · 85 adegan berbeda · aktif di antrean IG/Threads' if live else 'Visual versi 3 · 85 adegan baru · versi 2 tetap terjadwal sampai penggantian selesai'
footer_text = f'{receipt["updated_posts"]} posting dengan {receipt["updated_slides"]} slide sudah diperbarui dan diverifikasi melalui API Loka. ID posting dan jam tayang tetap; posting yang sudah terbit dipertahankan.' if live else 'Versi ini tersimpan lokal sebagai materi tinjauan. Tidak ada unggahan atau perubahan jadwal Instagram/Threads.'
esc = html.escape
options = ''.join(f'<option value="{esc(label)}">{esc(label)}</option>' for label in dict.fromkeys(p['format_label'] for p in posts))
cards = []
for p in posts:
    archived = p['scheduled_at'][:10] < '2026-11-17'
    pictures = ''.join(f'<a href="{esc(f)}" target="_blank" aria-label="Buka slide {n}"><img loading="lazy" src="{esc(f)}" alt="Slide {n} dari {len(p["slides"])}: {esc(s["title"])}" width="1080" height="1350"><span>{n} / {len(p["slides"])}</span></a>' for n, (f,s) in enumerate(zip(p['files'],p['slides']),1))
    cards.append(f'''<article id="post-{p['number']}" data-format="{esc(p['format_label'])}" data-search="{esc((p['hook']+' '+p['pillar']+' '+p['scheduled_at']).lower())}">
    <div class="article-head"><div><p class="meta">{p['number']:02d} · {esc(p['format_label'])} · {len(p['slides'])} slide {'· AKTIF DI ANTREAN' if p['original_post_id'] in released_ids else ''}</p><h2>{esc(p['hook'])}</h2><p class="date">{'Jadwal' if live else 'Referensi jadwal lama'}: {esc(p['scheduled_at'][:16].replace('T',' '))} WIB {'· <strong>Arsip — versi asli sudah terbit; revisi ini tidak dipasang</strong>' if archived else ''}</p></div><a class="anchor" href="#post-{p['number']}">#{p['number']:02d}</a></div>
    <div class="slides">{pictures}</div>
    <details><summary>Caption Instagram</summary><pre>{esc(p['caption'])}</pre><button type="button" class="copy">Salin caption</button><span class="copy-state" aria-live="polite"></span></details>
    <details><summary>Teks Threads</summary><pre>{esc(p['threads_text'])}</pre><button type="button" class="copy">Salin teks</button><span class="copy-state" aria-live="polite"></span></details>
    </article>''')
style = '''
@font-face{font-family:Jakarta;src:url('assets/Jakarta-Medium.ttf');font-weight:500}@font-face{font-family:Jakarta;src:url('assets/Jakarta-Bold.ttf');font-weight:700}@font-face{font-family:Jakarta;src:url('assets/Jakarta-ExtraBold.ttf');font-weight:800}
*{box-sizing:border-box}html{scroll-behavior:smooth;scroll-padding-top:110px}body{margin:0;background:#edf0f5;color:#102545;font:500 15px/1.6 Jakarta,sans-serif}header{background:#0c203e;color:white;padding:52px max(24px,calc((100vw - 1350px)/2));}header img{width:150px;display:block;margin-bottom:35px}h1{font-size:clamp(30px,4vw,53px);line-height:1.15;letter-spacing:-1.6px;max-width:900px;margin:14px 0 20px;font-weight:800}header p{max-width:800px;color:#d6e3f5}header a{color:#dffa78}a{color:#125cff}.status{color:#dffa78;font-size:13px;letter-spacing:1.3px;text-transform:uppercase}.stats{display:flex;gap:12px;flex-wrap:wrap;margin-top:24px}.stats span{border:1px solid #778bad5c;border-radius:99px;padding:7px 16px}.toolbar{position:sticky;top:0;z-index:5;display:flex;gap:12px;padding:16px max(24px,calc((100vw - 1350px)/2));background:#f8fafdeF;border-bottom:1px solid #dae1ec;backdrop-filter:blur(12px);align-items:center}.toolbar input,.toolbar select{font:inherit;border:1px solid #c1cede;border-radius:10px;padding:11px 14px;color:#102545;background:white}.toolbar input{width:min(440px,40vw)}.toolbar .count{margin-left:auto;white-space:nowrap}main{max-width:1400px;margin:0 auto;padding:30px 24px 70px}article{background:white;border:1px solid #dce3ee;border-radius:20px;overflow:hidden;margin-bottom:28px;box-shadow:0 3px 13px #10254505}.article-head{display:flex;justify-content:space-between;gap:20px;padding:25px 26px 16px}.meta{font-size:12px;text-transform:uppercase;letter-spacing:1px;color:#125cff;font-weight:700;margin:0 0 8px}h2{font-size:24px;line-height:1.4;letter-spacing:-.5px;margin:0;font-weight:800}.date{font-size:12px;color:#5c6b80;margin:9px 0 0}.anchor{font-size:14px;font-weight:700;text-decoration:none}.slides{display:flex;gap:13px;padding:10px 26px 25px;overflow-x:auto;scroll-snap-type:x proximity}.slides a{position:relative;flex:0 0 265px;scroll-snap-align:start;text-decoration:none}.slides img{display:block;width:265px;height:auto;border-radius:10px;background:#dce3ed}.slides span{display:block;text-align:center;font-size:11px;color:#65758a;padding-top:7px}details{border-top:1px solid #e5ebf3;padding:15px 26px}summary{cursor:pointer;font-weight:700}pre{white-space:pre-wrap;font:500 14px/1.8 Jakarta,sans-serif;max-width:900px;color:#2c405e;margin-top:20px}.copy{font:700 13px Jakarta,sans-serif;border:0;border-radius:8px;padding:10px 15px;color:white;background:#125cff;cursor:pointer}.copy-state{font-size:12px;margin-left:12px}.empty{padding:40px;text-align:center;display:none}.note{margin:8px 0 28px;color:#586c88;font-size:13px}.bottom{color:#526880;font-size:13px;padding-top:12px}@media(max-width:700px){.toolbar{flex-wrap:wrap;padding:12px 16px;gap:8px}.toolbar input{width:calc(100% - 75px);flex:1}.toolbar select{max-width:170px}.toolbar .count{font-size:12px}.article-head{padding:20px 18px 10px}h2{font-size:20px}.slides{padding:10px 18px 22px}.slides a{flex-basis:245px}.slides img{width:245px}main{padding:20px 12px}details{padding:14px 18px}}
'''
script = '''
const search=document.querySelector('#search');const format=document.querySelector('#format');const articles=[...document.querySelectorAll('article')];
function filter(){let count=0;for(const article of articles){const visible=(!format.value||article.dataset.format===format.value)&&article.dataset.search.includes(search.value.toLowerCase().trim());article.hidden=!visible;if(visible)count++;}document.querySelector('#count').textContent=count+' materi';document.querySelector('.empty').style.display=count?'none':'block';}
search.addEventListener('input',filter);format.addEventListener('change',filter);
for(const button of document.querySelectorAll('.copy'))button.addEventListener('click',async()=>{const value=button.parentElement.querySelector('pre').textContent;try{await navigator.clipboard.writeText(value);button.nextElementSibling.textContent='Tersalin';}catch{const range=document.createRange();range.selectNodeContents(button.parentElement.querySelector('pre'));const selection=window.getSelection();selection.removeAllRanges();selection.addRange(range);button.nextElementSibling.textContent='Teks dipilih — gunakan Cmd/Ctrl+C';}});
'''
page = f'''<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Revisi materi IG · Loka Kasir</title><style>{style}</style></head><body>
<header><img src="assets/loka-white.svg" alt="Loka"><div class="status">{esc(status_text)}</div><h1>85 posting.<br>85 adegan yang berbeda.</h1><p>Setiap posting mendatang punya gambar baru yang dibuat khusus untuk topiknya: objek, tokoh, lokasi, dan sudut pandang berbeda. Foto, diorama 3D, clay, komik, kolase, serta gouache dipadukan dengan logo dan tipografi Loka. Caption, urutan cerita, dan jam tayang tetap.</p><div class="stats"><span>85 gambar baru</span><span>408 slide mendatang</span><span>8 gaya gambar</span><span>1 arsip dipertahankan</span></div><p><a href="art-gallery.html">Lihat seluruh gambar sumber</a> · <a href="preview.jpg">Perbandingan sampul</a> · <a href="../2026-nov-dec-v2/index.html">Versi 2</a> · <a href="calendar.md">Kalender materi</a></p></header>
<div class="toolbar"><input id="search" type="search" placeholder="Cari topik, hook, atau tanggal…" aria-label="Cari materi"><select id="format" aria-label="Filter format"><option value="">Semua format</option>{options}</select><span id="count" class="count">86 materi</span></div>
<main><p class="note">Geser deretan gambar untuk melihat seluruh carousel. Klik gambar untuk membuka JPG 1080 × 1350. {'Materi bertanda aktif sudah dipasang ke antrean. ' if live else 'Jadwal di sini hanya referensi. '}Materi yang sudah terbit tidak untuk diterbitkan ulang. Foto AI adalah ilustrasi, bukan testimoni pelanggan.</p>{''.join(cards)}<div class="empty">Materi tidak ditemukan.</div><p class="bottom">{esc(footer_text)}</p></main><script>{script}</script></body></html>'''
(ROOT/'index.html').write_text(page)
art_figures=''.join(f'<figure><a href="{esc(p["art"])}"><img loading="lazy" src="{esc(p["art"])}" alt="{esc(p["hook"])}" width="1080" height="1350"></a><figcaption><b>{p["number"]} · {esc(p["art_direction"]["style"])}</b><br>{esc(p["hook"])}</figcaption></figure>' for p in posts if p['number']>1)
(ROOT/'art-gallery.html').write_text(f'<!doctype html><html lang="id"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>85 gambar khusus · Loka</title><style>body{{margin:0;background:#e8edf4;color:#102545;font:15px/1.5 sans-serif}}header{{padding:32px;max-width:1000px}}h1{{font-size:36px;margin-bottom:10px}}main{{display:grid;grid-template-columns:repeat(auto-fit,minmax(210px,1fr));gap:20px;padding:0 28px 40px}}figure{{margin:0;background:white;border-radius:12px;overflow:hidden}}img{{width:100%;height:auto;display:block}}figcaption{{padding:12px;font-size:13px}}a{{color:#125cff}}</style><header><a href="index.html">← Semua carousel</a><h1>85 gambar, masing-masing untuk satu posting.</h1><p>Seluruh gambar baru dibuat dengan built-in image_gen. Adegan fiktif untuk ilustrasi, bukan dokumentasi atau testimoni merchant. Klik gambar untuk membuka sumber PNG. <a href="image-prompts.json">Prompt lengkap</a></p></header><main>{art_figures}</main></html>')
print(json.dumps({'gallery_posts':len(posts),'images':sum(len(p['files']) for p in posts)}))
